124	void reduce_check_buf_init_fp32(void* dst_buf, u64 count, int val, int op, int rank_size)
125	{
126	    float* f_tmp = NULL;
127	    f_tmp = (float*)dst_buf;
128	    if(op == HCCL_REDUCE_SUM)
129	    {
130	        for(u64 j = 0; j < count; ++j)
131	        {
132	            f_tmp[j] = val * rank_size;
133	        }
134	    }
135	    else if(op == HCCL_REDUCE_PROD)
136	    {
137	        for(u64 j = 0; j < count; ++j)
138	        {
139	            f_tmp[j] = pow(val, rank_size);
140	        }
141	    }
142	    else if(op == HCCL_REDUCE_MIN || op == HCCL_REDUCE_MAX)
143	    {
144	        for(u64 j = 0; j < count; ++j)
145	        {
146	            f_tmp[j] = val;
147	        }
148	    }
149	    return;
150	}
