156	    int n = 0;
157	    const int modulus = 128;
158	    const int maxAllowValue = 127;
159	    if(op == HCCL_REDUCE_SUM)
160	    {
161	        for(u64 j = 0; j < count; ++j)
162	        {
163	            n = (val % modulus) * rank_size;
164	            if(n > maxAllowValue)
165	            {
166	                n = maxAllowValue;
167	            }
168	            tmp[j] = n;//大于128取127
169	        }
170	    }
171	    else if(op == HCCL_REDUCE_PROD)
172	    {
173	        for(u64 j = 0; j < count; ++j)
174	        {
175	            n = ((int)pow(val % modulus, rank_size));//大于128取127
176	            if(n > maxAllowValue)
177	            {
178	                n = maxAllowValue;
179	            }
180	            tmp[j] = n;//大于128取127
181	        }
182	    }
183	    else if(op == HCCL_REDUCE_MIN || op == HCCL_REDUCE_MAX)
184	    {
185	        for(u64 j = 0; j < count; ++j)
186	        {
187	            if(val > maxAllowValue)
188	            {
189	                val = maxAllowValue;
190	            }
191	            tmp[j] = val % modulus;
192	        }
193	    }
194	    return;
195	}
