667	bool hccl_alltoall_check_result(const void *recv_buff, const std::size_t count, const int nRanks,
668	    const int rank, const std::vector<std::uint8_t> &pattern)
669	{
670	    if (recv_buff == nullptr) {
671	        return false;
672	    }
673	    if (count == 0) {
674	        return true;
675	    }
676	    const std::uint8_t *dst_buf = static_cast<const std::uint8_t *>(recv_buff);
677	    const std::size_t recv_count_by_every_rank = count / nRanks;
678	    const std::size_t start_offset = recv_count_by_every_rank * rank;
679	    bool isMatch = true;
680	    for (int i = 0; i < nRanks; ++i) {
681	        std::size_t pattern_offset = start_offset;
682	        for (std::size_t j = 0; j < recv_count_by_every_rank; ++j, ++pattern_offset) {
683	            if (dst_buf[i * recv_count_by_every_rank + j] != pattern[(pattern_offset) % pattern.size()]) {
684	                isMatch = false;
685	                printf("The data sent from rank[%d] to rank[%d] at the [%llu] byte position is wrong, "
686	                       "expected[%x], actual[%x]\n",
687	                    i,
688	                    rank,
689	                    static_cast<u64>(j),
690	                    pattern[(pattern_offset) % pattern.size()],
691	                    dst_buf[i * recv_count_by_every_rank + j]);
692	                break;
693	            }
694	        }
695	    }
696	    return isMatch;
697	}
