325	int HcclTest::check_data_count()
326	{
327	    if (data_parsed_begin <= 0 || data_parsed_end <= 0) {
328	        printf("invalid size specified for [-b,--minbytes] or [-e,--maxbytes]\n");
329	        return -1;
330	    }
331	    data->min_bytes = (u64)data_parsed_begin;
332	    data->max_bytes = (u64)data_parsed_end;
333	
334	    if (stepbytes_flag != 0 && temp_step_bytes < 0) {
335	        printf("Error: [-i,--stepbytes] must be greater than or equal to 0.\n");
336	        return -1;
337	    }
338	
339	    u32 defaultStepFactor = 10;
340	    if (data->max_bytes < data->min_bytes) {
341	        printf("invalid option: maxbytes < minbytes, Check the [-b,--minbytes] and [-e,--maxbytes] options.\n");
342	        return -1;
343	    } else {
344	        if (stepbytes_flag != 0) {  // 用户配置了增量步长
345	            data->step_bytes = temp_step_bytes;
346	        } else {  // 用户未配置增量步长
347	            if (data->max_bytes == data->min_bytes) {
348	                data->step_bytes =
349	                    1;  // 用户配置数据量的起始值和结束值相同，但未配置增量步长，为防止进入死循环，设置增量步长为1
350	            }
351	            if (data->max_bytes > data->min_bytes) {
352	                data->step_bytes = (data->max_bytes - data->min_bytes) / defaultStepFactor;
353	            }
354	        }
355	    }
356	
357	    // 数据量需要被ranksize整除
358	    if (need_ranksize_alignment) {
359	        // 计算对齐大小：rank_size * BUF_ALGIN_SIZE(512)
360	        u64 align_size = rank_size * BUF_ALGIN_SIZE;
361	
362	        // 辅助函数：对齐字节数
363	        auto align_bytes = [&](u64 bytes) -> u64 {
364	            if (bytes < rank_size) {
365	                bytes = rank_size;
366	            }
367	            if (bytes > BUF_ALGIN_LINE) {
368	                // 大于BUF_ALGIN_LINE时，对齐到align_size的倍数
369	                bytes = (bytes / align_size) * align_size;
370	            } else {
371	                // 小于等于BUF_ALGIN_LINE时，对齐到rank_size的倍数
372	                bytes = (bytes / rank_size) * rank_size;
373	            }
374	            return bytes;
375	        };
376	
377	        // 对齐min_bytes和max_bytes
378	        data->min_bytes = align_bytes(data->min_bytes);
379	        data->max_bytes = align_bytes(data->max_bytes);
380	
381	        // 对齐step_bytes到rank_size的倍数（向上取整）
382	        data->step_bytes = ((data->step_bytes + rank_size - 1) / rank_size) * rank_size;
383	    }
384	
385	    if (stepfactor_flag != 0 && data->step_factor <= 1.0) {
386	        printf("Error: [-f,--stepfactor] Must be greater than 1.0f, Start step mod.\n");
387	        return -1;
388	    }
389	
390	    if (stepfactor_flag != 0 && stepbytes_flag != 0) {
391	        printf("Warning: [-f,--stepfactor] and [-i,--stepbytes] are set, [-f,--stepfactor] is enabled by default.\n");
392	    }
393	
394	    return 0;
395	}
