585	int HcclTest::parse_opt(int opt)
586	{
587	    switch (opt) {
588	        case 'a':
589	            accelerator_config = get_accelerator_config_value_from_str(optarg);
590	            break;
591	        case 'b':
592	            data_parsed_begin = parsesize(optarg);
593	            break;
594	        case 'e':
595	            data_parsed_end = parsesize(optarg);
596	            break;
597	        case 'i':
598	            stepbytes_flag++;
599	            temp_step_bytes = strtol_alldigit(optarg);
600	            break;
601	        case 'f':
602	            stepfactor_flag++;
603	            char *temp;
604	            data->step_factor = strtof(optarg, &temp);
605	            break;
606	        case 'n':
607	            iters = strtol_alldigit(optarg);
608	            break;
609	        case 'o':
610	            op_flag++;
611	            op_type = get_hccl_op_from_str(optarg);
612	            break;
613	        case 'd':
614	            dtype = get_hccl_dtype_from_str(optarg);
615	            break;
616	        case 'r':
617	            root_rank = strtol_alldigit(optarg);
618	            break;
619	        case 'w':
620	            warmup_iters = strtol_alldigit(optarg);
621	            break;
622	        case 'c':
623	            check = strtol_alldigit(optarg);
624	            break;
625	        case 'p':
626	            npus = strtol_alldigit(optarg);
627	            npus_flag = 1;
628	            break;
629	        case 'z':
630	            enable_zero_copy = std::stoi(optarg);
631	            break;
632	        case 'm':
633	            enable_symmetric_memory = std::stoi(optarg);
634	            break;
635	        case 's':
636	            nslb_flag = 1;
637	            break;
638	        case 't':
639	            only_device_exec_time = strtol_alldigit(optarg);
640	            break;
641	        case 'h':
642	            print_help();
643	            return 1;
644	        default:
645	            printf("invalid option \n");
646	            printf("Try [-h --help] for more information.\n");
647	            return -1;
648	    }
649	    return 0;
650	}
