685	int HcclTest::getAviDevs(const char *devs, std::vector<int> &dev_ids)
686	{
687	    std::string use_devs(devs);
688	    std::string pattern = ",";
689	    std::string::size_type pos;
690	    use_devs += pattern;
691	    size_t val_size = use_devs.size();
692	    for (size_t i = 0; i < val_size; ++i) {
693	        pos = use_devs.find(pattern, i);
694	        if (pos < val_size) {
695	            std::string s = use_devs.substr(i, pos);
696	            int tmp_rank = atoi(s.c_str());
697	            dev_ids.push_back(tmp_rank);
698	            i = pos + pattern.size() - 1;
699	        }
700	    }
701	
702	    return 0;
703	}
