    if (alloc_size > freeMem) {
        printf("Alloc memory size is larger than free memory, allocSize: %zu, freeMem: %zu, totalMem: %zu\n",
            alloc_size,
            freeMem,
            totalMem);
        return HCCL_E_MEMORY;
    }
